from locust import HttpUser, task, between

class Acheteur(HttpUser):
    wait_time = between(1, 3)

    @task(3)
    def consulter(self):
        self.client.get("/produits")

    @task(1)
    def commander(self):
        self.client.post("/commandes", json={"id": 7})
